"use client"

import React from "react"

import { IconChevronLgDown, IconHamburger } from "@intentui/icons"
import type {
  CellProps,
  ColumnProps,
  ColumnResizerProps,
  TableHeaderProps as HeaderProps,
  RowProps,
  TableBodyProps,
  TableProps as TablePrimitiveProps,
} from "react-aria-components"
import {
  Button,
  Cell,
  Collection,
  Column,
  ColumnResizer as ColumnResizerPrimitive,
  ResizableTableContainer,
  Row,
  TableBody as TableBodyPrimitive,
  TableHeader as TableHeaderPrimitive,
  Table as TablePrimitive,
  useTableOptions,
} from "react-aria-components"

import { composeTailwindRenderProps } from "@/lib/primitive"
import { twJoin, twMerge } from "tailwind-merge"
import { Checkbox } from "./checkbox"

interface TableProps extends TablePrimitiveProps {
  allowResize?: boolean
  ref?: React.Ref<HTMLTableElement>
}

const TableContext = React.createContext<TableProps>({
  allowResize: false,
})

const useTableContext = () => React.useContext(TableContext)

const Table = ({ children, className, ref, ...props }: TableProps) => {
  return (
    <TableContext.Provider value={props}>
      <div className="flow-root">
        <div className="relative w-full overflow-x-auto **:data-[slot=table-resizable-container]:overflow-auto">
          {props.allowResize ? (
            <ResizableTableContainer>
              <TablePrimitive
                className={composeTailwindRenderProps(
                  className,
                  "w-full min-w-full caption-bottom text-sm outline-hidden [--table-selected-bg:color-mix(in_oklab,var(--color-primary)_5%,white_90%)] dark:[--table-selected-bg:color-mix(in_oklab,var(--color-primary)_25%,black_70%)]",
                )}
                ref={ref}
                {...props}
              >
                {children}
              </TablePrimitive>
            </ResizableTableContainer>
          ) : (
            <TablePrimitive
              className={composeTailwindRenderProps(
                className,
                "w-full min-w-full caption-bottom border-collapse border-spacing-1 text-sm [--table-selected-bg:color-mix(in_oklab,var(--color-primary)_5%,white_90%)] dark:[--table-selected-bg:color-mix(in_oklab,var(--color-primary)_25%,black_70%)]",
              )}
              {...props}
              ref={ref}
            >
              {children}
            </TablePrimitive>
          )}
        </div>
      </div>
    </TableContext.Provider>
  )
}

const ColumnResizer = ({ className, ...props }: ColumnResizerProps) => (
  <ColumnResizerPrimitive
    {...props}
    className={composeTailwindRenderProps(
      className,
      "absolute top-0 right-0 bottom-0 grid w-px &[data-resizable-direction=left]:cursor-e-resize &[data-resizable-direction=right]:cursor-w-resize touch-none place-content-center px-1 data-[resizable-direction=both]:cursor-ew-resize [&[data-resizing]>div]:bg-primary",
    )}
  >
    <div className="h-full w-px bg-border py-2.5" />
  </ColumnResizerPrimitive>
)

const TableBody = <T extends object>(props: TableBodyProps<T>) => (
  <TableBodyPrimitive data-slot="table-body" {...props} />
)

interface TableColumnProps extends ColumnProps {
  className?: string
  isResizable?: boolean
}

const TableColumn = ({ isResizable = false, className, ...props }: TableColumnProps) => {
  return (
    <Column
      data-slot="table-column"
      {...props}
      className={composeTailwindRenderProps(
        className,
        twJoin(
          "relative allows-sorting:cursor-pointer whitespace-nowrap px-3 py-2.5 text-left font-medium outline-hidden data-dragging:cursor-grabbing [&:has([slot=selection])]:pr-0",
          isResizable && "overflow-hidden truncate",
        ),
      )}
    >
      {(values) => (
        <div className="flex items-center gap-2 **:data-[slot=icon]:shrink-0">
          <>
            {typeof props.children === "function" ? props.children(values) : props.children}
            {values.allowsSorting && (
              <span
                className={twMerge(
                  "grid size-[1.15rem] flex-none shrink-0 place-content-center rounded bg-secondary text-fg *:data-[slot=icon]:size-3.5 *:data-[slot=icon]:shrink-0 *:data-[slot=icon]:transition-transform *:data-[slot=icon]:duration-200",
                  values.isHovered ? "bg-secondary-fg/10" : "",
                  className,
                )}
              >
                <IconChevronLgDown
                  className={values.sortDirection === "ascending" ? "rotate-180" : ""}
                />
              </span>
            )}
            {isResizable && <ColumnResizer />}
          </>
        </div>
      )}
    </Column>
  )
}

interface TableHeaderProps<T extends object> extends HeaderProps<T> {
  ref?: React.Ref<HTMLTableSectionElement>
}

const TableHeader = <T extends object>({
  children,
  ref,
  columns,
  ...props
}: TableHeaderProps<T>) => {
  const { selectionBehavior, selectionMode, allowsDragging } = useTableOptions()
  return (
    <TableHeaderPrimitive data-slot="table-header" ref={ref} {...props}>
      {allowsDragging && <Column className="max-w-7" />}
      {selectionBehavior === "toggle" && (
        <Column className="max-w-7 px-3 py-2.5">
          {selectionMode === "multiple" && <Checkbox slot="selection" />}
        </Column>
      )}
      <Collection items={columns}>{children}</Collection>
    </TableHeaderPrimitive>
  )
}

interface TableRowProps<T extends object> extends RowProps<T> {
  ref?: React.Ref<HTMLTableRowElement>
}

const TableRow = <T extends object>({
  children,
  className,
  columns,
  id,
  ref,
  ...props
}: TableRowProps<T>) => {
  const { selectionBehavior, allowsDragging } = useTableOptions()
  return (
    <Row
      ref={ref}
      data-slot="table-row"
      id={id}
      {...props}
      className={composeTailwindRenderProps(
        className,
        twJoin(
          "group focus-visible:-outline-offset-2 relative cursor-default border bg-bg selected:bg-(--table-selected-bg) text-muted-fg ring-primary selected:hover:bg-(--table-selected-bg)/70 focus-visible:outline focus-visible:outline-blue-500 dark:selected:hover:bg-[color-mix(in_oklab,var(--color-primary)_30%,black_70%)]",
          ((props.href && !props.isDisabled) || props.onAction) &&
            "cursor-pointer hover:bg-secondary/50 hover:text-secondary-fg",
        ),
      )}
    >
      {allowsDragging && (
        <TableCell className="cursor-grab p-0 ring-primary data-dragging:cursor-grabbing">
          <Button
            slot="drag"
            className="ml-0.5 grid place-content-center rounded-xs p-2 outline-hidden focus-visible:ring focus-visible:ring-ring"
          >
            <IconHamburger />
          </Button>
        </TableCell>
      )}
      {selectionBehavior === "toggle" && (
        <TableCell>
          <span
            aria-hidden
            className="absolute inset-y-0 left-0 hidden h-full w-0.5 bg-primary group-selected:block"
          />
          <Checkbox slot="selection" />
        </TableCell>
      )}
      <Collection items={columns}>{children}</Collection>
    </Row>
  )
}

const TableCell = ({ className, ...props }: CellProps) => {
  const { allowResize } = useTableContext()
  return (
    <Cell
      data-slot="table-cell"
      {...props}
      className={composeTailwindRenderProps(
        className,
        twJoin(
          "group whitespace-nowrap px-3 py-2.5 align-middle outline-hidden",
          allowResize && "overflow-hidden truncate",
        ),
      )}
    />
  )
}

Table.Body = TableBody
Table.Cell = TableCell
Table.Column = TableColumn
Table.Header = TableHeader
Table.Row = TableRow

export type { TableProps, TableColumnProps, TableRowProps }
export { Table }
